  name: "ReduceUserAgentDataLinuxPlatformVersion",
  status: {"Linux": "stable"},
}

BASE_FEATURE(k{{feature.base_feature}},
    "{{feature.base_feature}}",
{% if feature.base_feature_status %}
    base::FEATURE_{{'ENABLED' if feature.base_feature_status == 'enabled' else 'DISABLED'}}_BY_DEFAULT
{% else %}
{% if feature.status_type == 'str' %}
    base::FEATURE_{{'ENABLED' if feature.status == 'stable' else 'DISABLED'}}_BY_DEFAULT
{% else %}
{% for platform in platforms %}
#if {{platform_buildflag(platform)}}
    base::FEATURE_{{'ENABLED' if feature.status[platform] == 'stable' else 'DISABLED'}}_BY_DEFAULT
#endif

std::string GetPlatformVersion() {
#if BUILDFLAG(IS_LINUX)
  // TODO(crbug.com/40245146): Remove this Blink feature
  if (base::FeatureList::IsEnabled(
          blink::features::kReduceUserAgentDataLinuxPlatformVersion)) {
    return std::string();
  }
#endif
...
#if BUILDFLAG(IS_WIN)
  return GetWindowsPlatformVersion();
#elif BUILDFLAG(IS_FUCHSIA)
  return std::string();
#else
  int32_t major, minor, bugfix = 0;
  base::SysInfo::OperatingSystemVersionNumbers(&major, &minor, &bugfix);
  return base::StringPrintf("%d.%d.%d", major, minor, bugfix);

...
metadata.platform_version = GetPlatformVersion();

void SetHeaderToString(net::HttpRequestHeaders* headers,
                       WebClientHintsType client_hint_type,
                       const std::string& value) {
  headers->SetHeader(network::GetClientHintToNameMap().at(client_hint_type),
                     value);
}

...

if (ShouldAddClientHint(data, WebClientHintsType::kUAPlatformVersion)) {
  AddUAHeader(headers, WebClientHintsType::kUAPlatformVersion,
              SerializeHeaderString(ua_metadata->platform_version));
}

